pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }
    function testFuzz_property(address from, address[] calldata _tos, uint v) public {
        vm.assume(_tos.length > 0);
        AmountChecker checker = new AmountChecker(v);
        bool ok;
        try c.transfer(from, address(checker), _tos, v) returns (bool res) {
            ok = res;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract AmountChecker {
    uint expected;
    constructor(uint _expected) { expected = _expected; }
    function transferFrom(address, address, uint amount) external view returns (bool) {
        require(amount == expected, "wrong amount");
        return true;
    }
}
